import { Stack, useRouter } from "expo-router";
import { StatusBar } from "expo-status-bar";

import { User } from "firebase/auth";
import { useEffect } from "react";
import { Platform, StatusBar as RNStatusBar } from "react-native";
import "react-native-reanimated";

import { ConnectionIndicator } from "@/components/ConnectionIndicator";
import { DeepLinkHandler } from "@/components/DeepLinkHandler";
import { CacheProvider } from "@/contexts/CacheContext";
import { ThemeProvider, useTheme } from "@/contexts/ThemeContext";
import { onAuthChange } from "@/services/authService";
import { startPushNotificationRegistration } from "@/services/notificationService";
import { getPersistentSession } from "@/services/persistenceSessionService";
import { sessionManager } from "@/services/sessionManager";
import {
  initializeTokenRefresh,
  stopTokenRefresh,
} from "@/services/tokenRefreshService";

// Initial route is index (WelcomeScreen) by default

// Inner component that uses theme
function AppContent() {
  useTheme();
  const router = useRouter();

  // Initialize session manager for rich, smooth session handling
  useEffect(() => {
    sessionManager.initialize();
    return () => sessionManager.cleanup();
  }, []);

  // Initialize automatic token refresh when user is authenticated
  useEffect(() => {
    const unsubscribe = onAuthChange((user: User | null) => {
      if (user) {
        // User is authenticated, start automatic token refresh
        initializeTokenRefresh();
      } else {
        // User is signed out, stop token refresh
        stopTokenRefresh();
      }
    });

    return () => {
      unsubscribe();
      stopTokenRefresh();
    };
  }, []);

  // Register push notifications once auth is ready (and on every sign-in).
  useEffect(() => {
    const unsubscribe = startPushNotificationRegistration();
    return unsubscribe;
  }, []);

  // WhatsApp-like persistence:
  // If a verified consumer session marker exists on this device,
  // skip login and go straight to the consumer dashboard.
  //
  // IMPORTANT: Only route after Firebase auth has a real user.
  // Otherwise, downstream token flows may start without any real cached account.
  useEffect(() => {
    let cancelled = false;

    const bootstrap = async () => {
      try {
        const session = await getPersistentSession();
        if (cancelled) return;

        if (
          session?.role === "consumer" &&
          session?.emailVerified &&
          session?.uid
        ) {
          // Wait for Firebase auth to confirm the user.
          // This avoids routing based only on local markers.
          const { auth } = await import("@/config/firebase");

          // NOTE: avoid require("firebase/auth") patterns (eslint no-require-imports).

          if (auth.currentUser?.uid === session.uid) {
            router.replace("/(tabs)");
            return;
          }

          // If auth isn't ready yet, wait briefly for auth state.
          await new Promise<void>((resolve) => {
            const { onAuthStateChanged } = require("firebase/auth");
            const unsub = onAuthStateChanged(auth, (user: any) => {
              if (user?.uid === session.uid) {
                router.replace("/(tabs)");
              }
              unsub();
              resolve();
            });

            setTimeout(() => {
              unsub();
              resolve();
            }, 2000);
          });
        }
      } catch {
        // Ignore and fall back to normal navigation
      }
    };

    void bootstrap();

    return () => {
      cancelled = true;
    };
  }, [router]);

  useEffect(() => {
    if (Platform.OS === "android") {
      RNStatusBar.setBarStyle("dark-content", true);
      RNStatusBar.setTranslucent(false);
    }
  }, []);

  return (
    <>
      <StatusBar style="dark" />
      <DeepLinkHandler>
        <ConnectionIndicator />
        <Stack screenOptions={{ headerShown: false }}>
          <Stack.Screen name="index" />
          <Stack.Screen name="role-select" />
          <Stack.Screen name="verify-email" />
          <Stack.Screen name="terms" />
          <Stack.Screen name="privacy" />
          <Stack.Screen name="(tabs)" />
        </Stack>
      </DeepLinkHandler>
    </>
  );
}

export default function RootLayout() {
  return (
    <CacheProvider warmOnMount={true}>
      <ThemeProvider>
        <AppContent />
      </ThemeProvider>
    </CacheProvider>
  );
}

